old2='''    private static (AtmResult Result, NoteCounts StockAfter) Expected('''
new2='''    private static readonly System.Collections.Concurrent.ConcurrentDictionary<(int, NoteCounts, Denomination?), NoteCounts?> BestCombination = new();

    /// <summary>Énumère toutes les combinaisons possibles et garde la plus courte qui fait exactement le montant.</summary>
    private static NoteCounts? Fewest((int Amount, NoteCounts Stock, Denomination? Jammed) key)
    {
